using System; using Inu.Kernel.InterruptDispatch; namespace Inu.Samples.InterruptHandler; public static unsafe class Sample { private static UInt64 _count; public static Boolean Install(out Byte vector){ vector=KernelInterruptDispatch.AllocateVector(); return vector!=0 && KernelInterruptDispatch.Register(vector,&OnInterrupt,0UL); } private static Boolean OnInterrupt(Byte vector,UInt64 cookie){_count++;return true;} public static UInt64 Count()=>_count; }
